def best_shift_score(F,P):
 # allow integer translation while all cells in pattern footprint remains within 6x6
 h=len(patterns[P]); w=max(map(len,patterns[P]))
 best=0; loc=None
 for dy in range(7-h):
  for dx in range(7-w):
   shifted={(y+dy,x+dx) for y,x in motifs[P]}
   s=len(F&shifted)
   if s>best: best,loc=s,(dy,dx)
 return best,loc
for f,F in frames.items():
 print(f, {p:best_shift_score(F,p) for p in patterns})

