import numpy as np
Fsets=list(frames.values())
def transforms(S,h,w):
 arr=np.zeros((h,w),int)
 for y,x in S: arr[y,x]=1
 out=[]
 for k in range(4):
  a=np.rot90(arr,k)
  for fl in [False,True]:
   b=np.fliplr(a) if fl else a
   yy,xx=np.where(b)
   if len(yy):
    b=b[yy.min():yy.max()+1,xx.min():xx.max()+1]
   out.append({(y,x) for y in range(b.shape[0]) for x in range(b.shape[1]) if b[y,x]})
 return out
